export const generateQuestions = async (
  subject: Subject,
  difficulty: Difficulty,
  count: number
): Promise<Question[]> => {
  const apiKey = process.env.API_KEY;

  // FALLBACK: If no API key, return MOCK data immediately (Practice Mode)
  if (!apiKey || apiKey.trim() === '') {
    console.warn("No API Key found. Switching to Mock Data Mode.");
    await new Promise(resolve => setTimeout(resolve, 800)); // Fake delay for realism

    const mockPool = subject === Subject.ARITHMETIC ? MOCK_ARITHMETIC : MOCK_REASONING;
    // Duplicate pool if requested count is higher than pool
    let results = [...mockPool];
    while(results.length < count) {
      results = [...results, ...mockPool.map(q => ({...q, id: q.id + 1000}))];
    }
    return results.slice(0, count);
  }

  const ai = new GoogleGenAI({ apiKey });
  const modelName = "gemini-3-flash-preview";

  let prompt = "";

  if (subject === Subject.ARITHMETIC) {
    prompt = `
      You are 'Shubham AptiMaster', a strict examiner for top-tier Indian Government Competitive Exams (SSC CGL, IBPS PO, UPSC CSAT).
      Generate exactly ${count} unique, high-quality Arithmetic questions.
      Difficulty: ${difficulty}.

      MANDATORY TOPIC DISTRIBUTION (Mix these):
      - Percentage & Average
      - Ratio & Proportion
      - Profit and Loss & Discount
      - Time and Work
      - Time, Speed and Distance
      - Simple & Compound Interest
      - Data Interpretation (Caselet)

      Context: Questions must be conceptually tricky but solvable within 30-45 seconds using shortcuts.
      Do not use complex LaTeX. Use plain text.
    `;
  } else {
    prompt = `
      You are 'Shubham AptiMaster', a strict examiner for Indian Government Exams.
      Generate exactly ${count} unique Reasoning questions.
      Difficulty: ${difficulty}.

      MANDATORY RULES:
      1. **Topic Mix**: Include both Verbal (Syllogism, Blood Relations, Coding-Decoding) and **Non-Verbal** (Series, Analogies, Odd One Out, Mirror Images).
      2. **Non-Verbal Questions**: For at least 30-40% of questions, you MUST provide a visual representation. 
         - Generate a **clean, simple SVG code string** in the 'figureSVG' field.
         - The SVG should draw the 'Problem Figures' and the 'Answer Figures' inside one canvas.
         - Use white or light-colored strokes (stroke="currentColor") suitable for a dark background.
         - ViewBox should be standard like "0 0 400 200".
      3. **Uniqueness**: Do not repeat logic consecutively.
    `;
  }

  const questionSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        topic: { type: Type.STRING },
        text: { type: Type.STRING },
        figureSVG: { 
          type: Type.STRING, 
          description: "Optional. A complete, valid <svg> string for non-verbal reasoning questions. Must include viewBox. Stroke colors should be light/white." 
        },
        options: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING }
        },
        correctAnswerIndex: { type: Type.INTEGER },
        explanation: { type: Type.STRING }
      },
      required: ["id", "text", "options", "correctAnswerIndex", "explanation", "topic"]
    }
  };

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: questionSchema,
        systemInstruction: "You are a competitive exam setter. Output raw JSON only. For non-verbal reasoning, ensure SVGs are valid and visible on dark backgrounds."
      }
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from AI");

    const questions = JSON.parse(jsonText) as Question[];

    return questions.map((q, index) => ({
      ...q,
      id: index
    }));

  } catch (error: any) {
    console.error("GenAI Error:", error);
    // If quota exceeded or permission denied, fall back to mock
    if (error.message.includes('403') || error.message.includes('permission denied') || error.message.includes('quota')) {
       console.warn("API Error. Falling back to Mock Data.");
       return subject === Subject.ARITHMETIC ? MOCK_ARITHMETIC.slice(0, count) : MOCK_REASONING.slice(0, count);
    }
    throw error;
  }
};

import React, { useState } from 'react';
import WelcomeScreen from './components/WelcomeScreen';
import QuizScreen from './components/QuizScreen';
import ResultsScreen from './components/ResultsScreen';
import AnalyticsScreen from './components/AnalyticsScreen';
import { QuizConfig, Question, QuizState, Subject } from './types';
import { generateQuestions } from './services/geminiService';
import { AlertTriangle, Settings, Key, Zap } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<'welcome' | 'quiz' | 'results' | 'analytics'>('welcome');
  const [config, setConfig] = useState<QuizConfig | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [quizResultState, setQuizResultState] = useState<QuizState | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<React.ReactNode | null>(null);
  const [isDemoMode, setIsDemoMode] = useState(false);

  const handleStartQuiz = async (newConfig: QuizConfig) => {
    setIsLoading(true);
    setError(null);
    setConfig(newConfig);

    try {
      const generatedQuestions = await generateQuestions(
        newConfig.subject,
        newConfig.difficulty,
        newConfig.questionCount
      );

      // Check if we are in demo mode (using mock data usually returns smaller IDs or specific text)
      // Or simply check if env key is missing
      if (!process.env.API_KEY) {
          setIsDemoMode(true);
      } else {
          setIsDemoMode(false);
      }

      setQuestions(generatedQuestions);
      setAppState('quiz');
    } catch (err: any) {
      console.error(err);
      setError("Exam construction failed. Please verify your internet connection and try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleFinishQuiz = (resultState: QuizState) => {
    setQuizResultState(resultState);
    setAppState('results');
  };

  const handleRestart = () => {
    setAppState('welcome');
    setConfig(null);
    setQuestions([]);
    setQuizResultState(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-zinc-950 font-inter selection:bg-amber-500 selection:text-black">
      {appState !== 'quiz' && (
        <nav className="bg-zinc-900/80 backdrop-blur-md border-b border-zinc-800 px-6 py-4 flex items-center justify-between sticky top-0 z-50 no-print">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={handleRestart}>
            <div className="w-10 h-10 bg-gradient-to-br from-amber-400 to-orange-600 rounded-xl flex items-center justify-center text-black font-bold text-xl shadow-lg shadow-amber-900/20 group-hover:scale-105 transition-transform">
              S
            </div>
            <div>
               <span className="font-bold text-xl tracking-tight text-white font-space">Shubham <span className="text-amber-500">AptiMaster</span></span>
               <div className="text-[10px] text-zinc-500 uppercase tracking-widest leading-none">Govt Exam Specialist</div>
            </div>
          </div>
          <div className="hidden sm:flex items-center gap-4 text-xs font-bold text-zinc-500 uppercase tracking-wider">
            {!process.env.API_KEY && (
                <span className="flex items-center gap-1 text-emerald-400 bg-emerald-900/30 px-2 py-1 rounded border border-emerald-900/50">
                    <Zap size={12} fill="currentColor" /> Practice Mode
                </span>
            )}
            <span>SSC</span>
            <span className="w-1 h-1 rounded-full bg-zinc-700"></span>
            <span>Bank PO</span>
          </div>
        </nav>
      )}

      <main className="container mx-auto">
        {error && (
          <div className="max-w-2xl mx-auto mt-8 bg-red-900/20 border border-red-500/50 text-red-100 px-6 py-4 rounded-xl relative flex items-start gap-4 animate-fade-in" role="alert">
            <AlertTriangle className="flex-shrink-0 mt-1 text-red-500" />
            <div className="flex-1">{error}</div>
          </div>
        )}

        {isDemoMode && appState === 'quiz' && (
             <div className="fixed top-20 right-4 z-40 bg-zinc-800/80 backdrop-blur border border-zinc-700 text-zinc-400 text-xs px-3 py-1.5 rounded-full flex items-center gap-2 pointer-events-none">
                 <Zap size={12} className="text-amber-500" /> Practice Data (Offline)
             </div>
        )}

        {appState === 'welcome' && (
          <WelcomeScreen 
            onStart={handleStartQuiz} 
            onViewAnalytics={() => setAppState('analytics')}
            isLoading={isLoading} 
          />
        )}

        {appState === 'analytics' && (
            <AnalyticsScreen onBack={() => setAppState('welcome')} />
        )}

        {appState === 'quiz' && config && (
          <QuizScreen 
            questions={questions} 
            timeLimitMinutes={config.timeLimitMinutes}
            onFinish={handleFinishQuiz}
            subject={config.subject}
          />
        )}

        {appState === 'results' && quizResultState && config && (
          <ResultsScreen 
            questions={questions}
            state={quizResultState}
            totalTimeMinutes={config.timeLimitMinutes}
            subject={config.subject}
            difficulty={config.difficulty}
            onRestart={handleRestart}
            onViewAnalytics={() => setAppState('analytics')}
          />
        )}
      </main>
    </div>
  );
};

